    for vec in probe_vecs:
        for a in range(natoms):
            if vec[a]:
                probe_pos[a] |= bit
        bit <<= 1

    lit_mask = []
    for a in range(natoms):
        lit_mask.append(pos_mask[a])
        lit_mask.append(full ^ pos_mask[a])
    lit_neg = [full ^ m for m in lit_mask]

    src_masks = train_source_masks(train_source_names,
                                   [m[2] for m in train_meta], n_train)

    lit_ok = []
    for l in range(2 * natoms):
        mask = lit_mask[l]
        ok = True
        for sm in src_masks:
            if (mask & sm).bit_count() < S:
                ok = False
                break
        lit_ok.append(ok)

    probe_lit = []
    for a in range(natoms):
        probe_lit.append(probe_pos[a])
        probe_lit.append(probe_full ^ probe_pos[a])

    eligible = []
    for lits in iter_clauses(natoms, B):
        good = True
        for l in lits:
            if not lit_ok[l]:
                good = False
                break
        if not good:
            continue
        cmask = 0
        for l in lits:
            cmask |= lit_mask[l]
        if cmask != full:
            continue
        pmask = 0
        for l in lits:
            pmask |= probe_lit[l]
        if pmask == probe_full:
            continue
        ok = True
        for i, l in enumerate(lits):
            wm = lit_mask[l]
            for j, l2 in enumerate(lits):
                if j != i:
                    wm &= lit_neg[l2]
            for sm in src_masks:
                if (wm & sm).bit_count() < W:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            eligible.append((pmask, lits))

    sig_map = {}
    for pmask, lits in eligible:
        entry = sig_map.get(pmask)
        if entry is None:
            sig_map[pmask] = [1, lits, [lits]]
        else:
            entry[0] += 1
            entry[2].append(lits)
    sig_width = (n_probe + 3) // 4
